// Generates the bundled content used by the app and the website from content/.
// Usage: node scripts/build-content.mjs [--check]
// --check exits non-zero when a generated file is out of date instead of writing it.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const read = p => fs.readFileSync(path.join(root, p), 'utf8');
const check = process.argv.includes('--check');

function parseArticle(id, text) {
  const lines = text.replace(/\r\n/g, '\n').trim().split('\n');
  if (!lines[0].startsWith('# ')) throw new Error(`content/articles/${id}.md must start with "# Title"`);
  const title = lines[0].slice(2).trim();
  let related = [];
  const relIndex = lines.findIndex(l => /^Related:\s*/.test(l));
  if (relIndex >= 0) { related = lines[relIndex].replace(/^Related:\s*/, '').split(',').map(s => s.trim()).filter(Boolean); lines.splice(relIndex, 1); }
  const body = lines.slice(1).join('\n').trim();
  const firstPara = body.split('\n\n').find(block => !/^(#|\||\s*[-*]\s|\s*\d+\.)/.test(block.trim())) || '';
  const summary = firstPara.replace(/\*\*|`/g, '').replace(/\s+/g, ' ').trim();
  return { id, title, summary, related, body };
}

export function build() {
  const features = JSON.parse(read('content/features.json'));
  const changelog = JSON.parse(read('content/changelog.json'));
  const dir = path.join(root, 'content/articles');
  const articles = fs.readdirSync(dir).filter(f => f.endsWith('.md')).sort().map(f => parseArticle(f.slice(0, -3), fs.readFileSync(path.join(dir, f), 'utf8')));
  const ids = new Set(articles.map(a => a.id));
  const problems = [];
  const seen = new Set();
  const groups = new Set(features.groups.map(g => g[0]));
  for (const item of features.items) {
    if (seen.has(item.id)) problems.push(`duplicate feature id ${item.id}`);
    seen.add(item.id);
    if (!features.statuses[item.status]) problems.push(`${item.id}: unknown status ${item.status}`);
    if (!groups.has(item.group)) problems.push(`${item.id}: unknown group ${item.group}`);
    if (item.article && !ids.has(item.article)) problems.push(`${item.id}: article ${item.article} is missing`);
    if (['built', 'partial'].includes(item.status) && !item.note) problems.push(`${item.id}: built items need a note`);
  }
  for (const a of articles) for (const r of a.related) if (!ids.has(r)) problems.push(`article ${a.id}: related article ${r} is missing`);
  if (problems.length) throw new Error(`Content problems:\n- ${problems.join('\n- ')}`);
  const data = { features, articles, changelog };
  const js = `// Generated by scripts/build-content.mjs from content/. Do not edit by hand.\n'use strict';\n(function (root) { const data = ${JSON.stringify(data)};\n  if (typeof module === 'object' && module.exports) module.exports = data; else root.Content = data; })(typeof window === 'undefined' ? globalThis : window);\n`;
  const order = features.groups;
  const label = { built: '[x]', partial: '[~]', planned: '[ ]', na: '[-]' };
  let md = '# Roadmap\n\nGenerated from `content/features.json` by `scripts/build-content.mjs`. `[x]` built, `[~]` partly built, `[ ]` not built yet, `[-]` does not apply.\n';
  for (const [key, name] of order) {
    md += `\n## ${name}\n\n`;
    for (const item of features.items.filter(i => i.group === key)) md += `- ${label[item.status]} **${item.title}**: ${item.note}\n`;
  }
  return { 'src/renderer/content.js': js, 'docs/content.js': js, 'ROADMAP.md': md, 'docs/regex.js': read('src/renderer/regex.js'), 'docs/markdown.js': read('src/renderer/markdown.js') };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  const outputs = build();
  let stale = [];
  for (const [file, content] of Object.entries(outputs)) {
    const target = path.join(root, file);
    const current = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : null;
    if (current === content) continue;
    if (check) stale.push(file); else { fs.mkdirSync(path.dirname(target), { recursive: true }); fs.writeFileSync(target, content); console.log(`wrote ${file}`); }
  }
  if (stale.length) { console.error(`Out of date, run npm run content:\n${stale.join('\n')}`); process.exit(1); }
}
